"""Conservative validation for SQL generated by a language model."""

import re
import sqlite3


SQL_INPUT_MESSAGE = (
    "Tutaj zadaj pytanie zwykłym językiem, np. „Ile jest zamówień?”. "
    "Ręczne zapytania SQL nie są obsługiwane. Kod nie został wykonany ani wysłany do AI."
)


def is_sql_input(text: str) -> bool:
    """Recognize pasted SQL locally, including comments and Markdown wrappers.

    This is an input guard, not the execution security boundary. SELECT is
    deliberately conservative; ordinary questions starting with 'With',
    'Update' or 'Explain' remain usable unless they contain SQL structure.
    """
    if re.search(r"```\s*(?:sql|sqlite|sqlite3)\b", text, re.IGNORECASE):
        return True
    code = re.sub(r"/\*[\s\S]*?\*/|--[^\n]*", " ", text).lstrip("\ufeff")
    identifier = r'(?:[\w.]+|"[^"]+"|`[^`]+`|\[[^\]]+\])'
    patterns = (
        r"\bSELECT\b",
        rf"\bWITH\s+(?:RECURSIVE\s+)?{identifier}\s*(?:\([^)]*\)\s*)?AS\s*\(",
        r"\b(?:INSERT|REPLACE)\s+(?:OR\s+\w+\s+)?INTO\b",
        rf"\bUPDATE\s+(?:OR\s+\w+\s+)?{identifier}\s+SET\b",
        r"\bDELETE\s+FROM\b",
        r"\b(?:CREATE|DROP|ALTER)\s+(?:(?:TEMP|TEMPORARY|UNIQUE|VIRTUAL)\s+)?(?:TABLE|VIEW|INDEX|TRIGGER)\b",
        r"\b(?:ATTACH|DETACH)\s+(?:DATABASE\s+)?['\"\w]",
        r"^\s*(?:PRAGMA|VACUUM|REINDEX|ANALYZE|BEGIN|COMMIT|ROLLBACK)\b",
    )
    return any(re.search(pattern, code, re.IGNORECASE | re.MULTILINE) for pattern in patterns)


FORBIDDEN_KEYWORDS = re.compile(
    r"\b(DROP|DELETE|UPDATE|INSERT|ALTER|CREATE|REPLACE|TRUNCATE|MERGE|"
    r"ATTACH|DETACH|PRAGMA|VACUUM|REINDEX|ANALYZE|LOAD_EXTENSION)\b",
    re.IGNORECASE,
)


class UnsafeSQLError(ValueError):
    """Raised when a query does not follow the application's SELECT-only rules."""


def mask_quoted_text(sql: str) -> str:
    """Hide SQLite string literals and quoted identifiers before keyword checks."""
    characters = list(sql)
    index = 0
    while index < len(sql):
        opener = sql[index]
        if opener not in "'\"`[":
            index += 1
            continue
        closer = "]" if opener == "[" else opener
        start = index
        index += 1
        while index < len(sql):
            if sql[index] == closer:
                if closer != "]" and index + 1 < len(sql) and sql[index + 1] == closer:
                    index += 2
                    continue
                index += 1
                break
            index += 1
        else:
            raise UnsafeSQLError("SQL zawiera niedomknięty tekst lub nazwę kolumny.")
        characters[start:index] = " " * (index - start)
    return "".join(characters)


def authorize_read(action: int, first: str | None, second: str | None,
                   database: str | None, trigger: str | None) -> int:
    """Let SQLite itself allow only reads and ordinary functions, including CTEs."""
    allowed = {sqlite3.SQLITE_SELECT, sqlite3.SQLITE_READ, sqlite3.SQLITE_FUNCTION, sqlite3.SQLITE_RECURSIVE}
    if action not in allowed:
        return sqlite3.SQLITE_DENY
    if action == sqlite3.SQLITE_FUNCTION and (second or "").lower() in {
        "load_extension", "readfile", "writefile", "shell",
    }:
        return sqlite3.SQLITE_DENY
    return sqlite3.SQLITE_OK


def validate_sql(sql: str) -> str:
    """Return one SELECT/CTE query or raise UnsafeSQLError.

    Ignore quoted text when checking keywords and separators. This filter is
    combined with SQLite's authorizer and a read-only connection in execute_query;
    syntax checking remains SQLite's responsibility.
    """
    if not isinstance(sql, str) or not sql.strip():
        raise UnsafeSQLError("Zapytanie SQL musi być niepustym tekstem.")

    query = sql.strip()
    if len(query) > 10000 or "\x00" in query:
        raise UnsafeSQLError("SQL może mieć maksymalnie 10 000 znaków i nie może zawierać znaku NUL.")
    masked = mask_quoted_text(query)
    if not re.match(r"^(SELECT|WITH)\b", masked, re.IGNORECASE) or not re.search(r"\bSELECT\b", masked, re.IGNORECASE):
        raise UnsafeSQLError("Dozwolone są tylko SELECT oraz WITH … SELECT.")

    if any(marker in masked for marker in ("--", "/*", "*/")):
        raise UnsafeSQLError("Komentarze SQL nie są dozwolone.")

    if query.endswith(";"):
        query = query[:-1].rstrip()

        masked = masked[:-1].rstrip()

    if ";" in masked:
        raise UnsafeSQLError("Dozwolone jest tylko jedno zapytanie SQL.")

    for forbidden in FORBIDDEN_KEYWORDS.finditer(masked):
        # REPLACE(...) transforms a value; REPLACE INTO writes to a table.
        if forbidden.group().upper() == "REPLACE" and re.match(r"\s*\(", masked[forbidden.end():]):
            continue
        raise UnsafeSQLError(
            f"Zablokowano niedozwolone słowo kluczowe: {forbidden.group().upper()}."
        )

    return query
